<script setup>
import{ref,reactive,onMounted,onUnmounted}from'vue';
import{requestApi}from'../../shared/infrastructure/http/apiClient.js';
import{submitOperation,pendingOperations,retryOperation}from'../../shared/infrastructure/http/pendingOperation.js';
const props=defineProps({identity:Object,online:Boolean}),devices=ref([]),selected=ref(null),error=ref(''),notice=ref(''),busy=ref(false),token=ref(''),pending=ref([]);
const form=reactive({name:'',serial:'',lotId:''}),calibration=reactive({calibratedAt:'',expiresAt:'',evidenceRef:''}),disableReason=ref(''),acknowledge=ref(false);
const can=p=>props.identity.permissions.includes(p),scope=()=>({tenantId:props.identity.tenantId,userId:props.identity.userId,resourceId:'devices'}),labels={Unconfirmed:'Conexión sin confirmar',Online:'En línea',Disconnected:'Sin comunicación reciente',Disabled:'Desactivado'};
let timer;
async function load(){if(!props.online)return;try{devices.value=(await requestApi('/api/v1/devices')).devices;pending.value=pendingOperations(scope());if(selected.value)selected.value=devices.value.find(d=>d.deviceId===selected.value.deviceId)??null;}catch(e){error.value=e.message;}}
onMounted(()=>{load();timer=setInterval(load,30000);});onUnmounted(()=>{clearInterval(timer);token.value='';});
async function act(action,path,payload){busy.value=true;error.value='';notice.value='';try{const r=await submitOperation(path,payload,scope(),action);notice.value='Operación de dispositivo confirmada.';await load();if(r.deviceId)selected.value=devices.value.find(d=>d.deviceId===r.deviceId);return r;}catch(e){error.value=e.message;pending.value=pendingOperations(scope());}finally{busy.value=false;}}
async function calibrate(){try{await act('calibration',`/api/v1/devices/${selected.value.deviceId}/calibrations`,{expectedVersion:selected.value.version,evidenceRef:calibration.evidenceRef,calibratedAt:new Date(calibration.calibratedAt).toISOString(),expiresAt:new Date(calibration.expiresAt).toISOString()});}catch(e){error.value='Indica fechas válidas de calibración y vencimiento.';}}
async function copyCredential(){try{await navigator.clipboard.writeText(token.value);notice.value='Credencial copiada.';}catch{error.value='No se pudo acceder al portapapeles.';}}
async function credential(){token.value='';busy.value=true;try{const r=await requestApi(`/api/v1/devices/${selected.value.deviceId}/credentials`,{method:'POST'});token.value=r.token;notice.value=r.notice;await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function retry(attempt){busy.value=true;try{await retryOperation(attempt);await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
</script>
<template><section class="panel" aria-label="Dispositivos"><h2>Dispositivos de captura</h2><p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert" role="status">{{notice}}</p>
 <p v-for="attempt in pending" :key="attempt.key" class="alert">Operación sin confirmar. <button @click="retry(attempt)" :disabled="busy||!online">Reintentar dispositivo</button></p>
 <form v-if="can('devices.manage')" @submit.prevent="act('register','/api/v1/devices',{...form})"><h3>Vincular balanza</h3><label>Nombre del dispositivo<input v-model="form.name" required maxlength="200" /></label><label>Identificador de balanza<input v-model="form.serial" required maxlength="100" /></label><label>Lote de la operación vinculada<input v-model="form.lotId" required /></label><button :disabled="busy||!online">Registrar dispositivo</button><p class="muted">El registro no confirma conectividad. Los reportes autenticados del dispositivo determinan su disponibilidad.</p></form>
 <button class="secondary" :disabled="busy||!online" @click="load">Actualizar dispositivos</button>
 <ul class="history-list"><li v-for="device in devices" :key="device.deviceId"><strong>{{device.name}} · {{labels[device.connection]}}</strong><p>{{device.serial}}</p><p v-if="device.battery!==null">Batería: {{device.battery}} % · {{device.batteryCurrent?'Reporte reciente':'Dato histórico, sin confirmar actualidad'}}</p><p>Última comunicación: {{device.lastCommunication?new Date(device.lastCommunication).toLocaleString('es-PE'):'Sin reportes válidos'}}</p><p v-for="alert in device.alerts.filter(a=>!a.resolvedAt)" :key="alert.id" class="alert error">{{alert.kind==='LowBattery'?'Batería inferior al 15 %':'Alerta de desconexión de cinco minutos'}}</p><button class="secondary" @click="selected=device;token=''">Ver dispositivo</button></li></ul>
 <section v-if="selected" class="lot-operations" aria-label="Detalle del dispositivo"><h3>{{selected.name}}</h3><p class="identifier">{{selected.deviceId}}</p><p>Estado: {{labels[selected.connection]}} · lote {{selected.lotId}}</p>
  <template v-if="can('devices.manage')&&selected.active"><button :disabled="busy||!online" @click="credential">Generar nueva credencial del dispositivo</button><p class="muted">Se muestra una sola vez y reemplaza la credencial anterior. Configúrala en el adaptador de la balanza.</p><label v-if="token">Credencial privada<input :value="token" type="password" readonly autocomplete="off" /><button type="button" class="secondary" @click="copyCredential">Copiar credencial</button><button type="button" class="secondary" @click="token=''">Ocultar y descartar credencial</button></label>
   <form @submit.prevent="calibrate"><h4>Registrar calibración</h4><label>Fecha de calibración<input v-model="calibration.calibratedAt" type="datetime-local" required /></label><label>Vencimiento de calibración<input v-model="calibration.expiresAt" type="datetime-local" required /></label><label>Documento de calibración<input v-model="calibration.evidenceRef" required /></label><button :disabled="busy||!online">Guardar calibración</button></form>
  </template>
  <form v-if="can('devices.disable')&&selected.active" @submit.prevent="act('disable',`/api/v1/devices/${selected.deviceId}/deactivation`,{expectedVersion:selected.version,reason:disableReason,acknowledgeOperationalImpact:acknowledge})"><h4>Desactivar dispositivo</h4><p class="alert error">La operación vinculada dejará de recibir nuevas mediciones válidas de esta balanza. El historial se conserva.</p><label>Motivo de desactivación<input v-model="disableReason" required /></label><label class="checkbox-label"><input v-model="acknowledge" type="checkbox" required /> Confirmo el efecto sobre la operación vinculada</label><button :disabled="busy||!online">Confirmar desactivación</button></form>
  <h4>Calibraciones</h4><ul><li v-for="c in selected.calibrations" :key="c.id">{{c.evidenceRef}} · {{new Date(c.calibratedAt).toLocaleDateString('es-PE')}} hasta {{new Date(c.expiresAt).toLocaleDateString('es-PE')}}</li></ul>
  <h4>Últimas mediciones</h4><ul><li v-for="r in selected.readings" :key="r.eventId">{{r.weight}} {{r.weightUnit}} · {{r.calibrationStatus==='Current'?'Calibración vigente al recibir':'Advertencia de calibración'}} · {{new Date(r.receivedAt).toLocaleString('es-PE')}}</li></ul>
  <details><summary>Historial de alertas y decisiones</summary><ul><li v-for="a in selected.alerts" :key="a.id">{{a.kind}} · {{a.resolvedAt?'Resuelta':'Activa'}} · {{new Date(a.openedAt).toLocaleString('es-PE')}}</li><li v-for="(a,i) in selected.audit" :key="'audit'+i">{{a.action}} · {{a.payload.reason??a.payload.kind??''}}</li></ul></details>
 </section>
</section></template>
